import { mergeIntervals } from "./intervals.mjs";
export function clipWindow(intervals, window) {
  return mergeIntervals(intervals.map(row => ({
    start: Math.max(row.start, window.start),
    end: Math.min(row.end, window.end),
  })).filter(row => row.start < row.end));
}
